const COURSE_MAP = (() => {
  const checkedDate = '2026-11-17';
  const sources = [];
  const source = (id, title, url, kind, application, limitation) => sources.push({id,title,url,kind,application,limitation,checkedDate});
  [1,2,3].forEach((n,i) => source('gn'+n,'Udir: Grunnleggende norsk NOR07-03, nivå '+n,'https://www.udir.no/lk20/nor07-03/kompetansemaal-og-vurdering/'+['kv1182','kv1183','kv1184'][i],'Læreplan','Gjeldende fra 1.8.2026. Pedagogisk kobling til språk-, tekst- og faglæring i skoleopplæring.','Planens nivåer er ikke satt lik CEFR. Oppgavene dekker utvalgte deler; skole/lærer avklarer opplæringsgrunnlaget.'));
  [1,2,3,4].forEach((n,i) => source('fov'+n,'Udir: Norsk for språklige minoriteter FOV NOR11-01, modul '+n,'https://www.udir.no/lk20/nor11-01/kompetansemaal-og-vurdering/'+['kv834','kv835','kv836','kv837'][i],'Læreplan','Supplerende målreferanse ved faktisk FOV-opplæring; gjeldende fra 1.8.2024.','Eget fag med sluttvurdering. Nettstedets moduler er ikke FOV-moduler og dokumenterer ikke bestått fag.'));
  source('hk-norsk','HK-dir: Norsk for voksne innvandrere, A1–B2','https://hkdir.no/dokumenter/les-dokumentet/laereplan-i-norsk-for-voksne-innvandrere/nivaer-og-kompetansemal','Læreplan','Ferdighetsreferanse for lesing, skriving, muntlig samhandling, lytting og mediering.','Læreplan under integreringsloven; gjelder ikke automatisk alle ungdommer. Nettarbeid alene dekker ikke alle ferdighetene.');
  source('samfunn','Forskrift om læreplan i samfunnskunnskap for voksne innvandrere','https://lovdata.no/dokument/SF/forskrift/2021-06-20-2054','Offisiell forskrift','Tematisk bakgrunn for utdanning, arbeidsliv, deltakelse og hverdagsliv.','Eget fag og egen målgruppe. Norskøving om samfunnstemaer dokumenterer ikke gjennomført samfunnskunnskap.');
  source('maalgruppe','Udir: Opplæring for nyankomne ungdom (16–18 år)','https://www.udir.no/regelverk-og-tilsyn/skole-og-opplaring/opplaring-for-nyankomne-ungdom/','Offisiell veiledning','Skille mellom videregående opplæring, FOV og samarbeidstilbud.','Alder og nasjonalitet avgjør ikke alene læreplan eller rettigheter. Ansvarlig opplæringstilbyder må avklare dette.');
  source('cefr','Council of Europe (2020): CEFR Companion volume','https://rm.coe.int/common-european-framework-of-reference-for-languages-learning-teaching/16809ea0d4','Referanseramme','Støtte for progresjon i resepsjon, produksjon, samhandling og mediering.','A0 er lokal pedagogisk startbetegnelse; Pre-A1 er rammeverkets betegnelse. Ingen likhet mellom leksjonsnummer, Udir-nivå, FOV-modul og CEFR-mestring.');
  source('spacing','Kim & Webb (2022): The Effects of Spaced Practice on Second Language Learning: A Meta-Analysis','https://doi.org/10.1111/lang.12479','Forskningsoversikt','Fordel øving over tid og undersøk hva eleven husker senere.','Ingen universelt optimal intervallrekke. Repetisjonsreglene er praktiske designvalg.');
  source('retrieval','Candry, Decloedt & Eyckmans (2020): Comparing the merits of word writing and retrieval practice for L2 vocabulary learning','https://doi.org/10.1016/j.system.2020.102206','Primærstudie','Hent fram kjent ordform etter introduksjon; unngå at alle forsøk blir avskrift.','Ungdom med engelsk omtrent på B1 lærte ukjente ord. Dokumenterer ikke et helt norskbegynnerkurs eller generell skrivekompetanse.');
  source('feedback','Kang & Han (2015): The Efficacy of Written Corrective Feedback in Improving L2 Written Accuracy: A Meta-Analysis','https://doi.org/10.1111/modl.12189','Forskningsoversikt','Gi avgrenset respons og la eleven bearbeide teksten.','Virkning på korrekthet varierer med nivå, kontekst og sjanger; viser ikke at strengsammenligning vurderer fri tekst.');
  source('tasks','Bryfonski & McKay (2019): TBLT implementation and evaluation: A meta-analysis','https://doi.org/10.1177/1362168817744389','Forskningsoversikt','Gi oppgaver et forståelig kommunikasjonsmål og en mottaker.','Gjelder hele programmer, ikke effektbevis for siden. Metodisk diskutert; våre aktiviteter beskrives som funksjonelle og oppgavestøttede.');
  source('gloss','Yanagisawa, Webb & Uchihara (2020): How do different forms of glossing contribute to L2 vocabulary learning from reading? A meta-regression analysis','https://doi.org/10.1017/S0272263119000688','Forskningsoversikt','Tilgjengelig betydnings- og ordstøtte, også på språk eleven kjenner.','Effekt på ordlæring fra glossing dokumenterer ikke et helt flerspråklig program. Oversettelsene trenger språklig kontroll.');
  source('translanguage','Huang & Chalmers (2023): Implementation and Effects of Pedagogical Translanguaging in EFL Classrooms: A Systematic Review','https://www.mdpi.com/2226-471X/8/3/194','Forskningsoversikt','Bruke elevens språkressurser til å avklare mening og sammenligne uttrykk.','Denne oversikten fant et usikkert robust effektgrunnlag. Det er ikke et bevis mot støtte, eller en garanti for effekten av ukrainsk/thai-støtten.');
  source('tasks-critique','Boers & Faez (nett 2023 / hefte 2026): Meta-analysis to estimate the relative effectiveness of TBLT programs: Are we there yet?','https://doi.org/10.1177/13621688231167573','Metodisk forskningsdiskusjon','Varsom overføring av samlede TBLT-effekter til enkeltressurser.','Diskuterer studiedesign og definisjoner; evaluerer ikke dette kurset.');
  source('tasks-comment','Xuan, Cheung & Liu (nett 2022 / hefte 2025): How effective is task-based language teaching to enhance second language learning? A technical comment on Bryfonski and McKay (2019)','https://doi.org/10.1177/13621688221131127','Metodisk forskningsdiskusjon','Ny analyse og kritikk av inklusjon, effektberegning og moderatorer.','Få egnede primærstudier; ingen direkte effektpåstand for nettstedet.');
  source('translanguage2026','Wang & Zhang (2026): A multilevel Bayesian meta-analysis of the effects of translanguaging pedagogy on L2 achievement','https://doi.org/10.1017/S0261444826101335','Forskningsoversikt','Nyere syntese rapporterer positive utbytter og variasjon mellom ferdigheter og utdanningsnivåer.','Ulike tiltak og målgrupper er samlet. Ingen dokumentasjon av akkurat ukrainsk/thai-støtten eller validering av appen.');
  const link = (sourceId,targetSummary,coverage='partial') => ({sourceId,targetSummary,coverage});
  const modules = [];
  const module = (id,title,stage,unitIds,goals,prerequisites,curriculumLinks,instruction,teacherScript,checklist) => modules.push({id,title,stage,unitIds,goals,prerequisites,curriculumLinks,teacherActivity:{instruction,teacherScript,checklist}});
  const range = (a,b) => Array.from({length:b-a+1},(_,i)=>'u'+(a+i));
  module('m01','Første ord og kontakt','a0',['u1','u2','a03','a04','a05'],['Knytte kjente ord til ting og personer.','Presentere seg og bruke korte kjente fraser.'],['Grunnleggende lese-/skriveferdigheter på et språk, eller tett individuell lærerstøtte.'],[link('gn1','Innøvde ord, fraser, enkle tekster og sammenligning med kjente språk.'),link('fov1','Språkstrategier og første funksjonelle språkbruk.'),link('gn1','Språklyder, bokstav–lyd, trykk og enkel samtale.','teacher-led')],'Lærerledet og planlagt. Vis ting og ordkort. Knytt bokstaver til modellerte språklyder, tilpasset elevens leseerfaring. Les så uten at eleven ser manuset.','Hei! Jeg heter Anna. Her er en bok. Her er en penn. Jeg har en bok. Hva heter du?',['Observer kobling mellom ord, bilde og uttale.','La eleven svare og stille et kjent spørsmål med støtte.','Dette er ikke en alfabetiseringsprøve.']);
  module('m02','Antall, egenskaper og handlinger','a0',['a06','a07','a08','a09','a10'],['Skille antall, farge, størrelse og kjente handlinger.','Hente fram ord og lage korte støttede svar.'],['Kjenne igjen sentrale ord fra modul 1.'],[link('gn1','Enkle begreper, tall og setninger.'),link('hk-norsk','Konkrete kjente emner med kontekststøtte.'),link('gn1','Muntlig bruk av tall, ord og fraser.','teacher-led')],'Lærerledet og planlagt. Legg fram bilder eller ting. Les uten synlig manus; la eleven peke før en kort samtale.','Én. To. Tre. Her er en rød bok. Her er en liten bok. Jeg leser. Jeg skriver.',['Observer om eleven skiller konkrete ord ved lytting.','La eleven beskrive ett bilde og svare.','Bruk bilder og kjente språk ved behov.']);
  module('m03','Fra ord til setninger','bridge',['u3','u4'],['Bruke kjente handlinger i en enkel setning.','Beskrive hvor en kjent ting er.'],['Kjente gjenstander, handlinger og støttet ordskriving.'],[link('gn1','Enkle setninger og alderstilpasset lesing.'),link('fov1','Funksjonell kommunikasjon om kjente temaer.'),link('gn1','Muntlige beskjeder og enkel samtale.','teacher-led')],'Lærerledet og planlagt. Les uten synlig manus. Bruk bilder ved andre gjennomlesing og la eleven svare muntlig.','Jeg har en bok. Jeg leser på skolen. Boka er i sekken. Pennen er på bordet. Hvor er boka?',['Eleven oppfatter handling og plassering med støtte.','Eleven svarer med en forståelig kort setning.','Skjermlesing registreres ikke som lytting.']);
  module('m03b','Min dag og korte beskjeder','a1',range(5,8),['Finne dag, tid og handling i en kort beskjed.','Skrive en kort plan med kjente mønstre.'],['Forstå kjente handlings- og stedssetninger fra bromodulen.'],[link('gn1','Enkle setninger, tekster, tall og språkstrategier.'),link('hk-norsk','Svært enkle meldinger og tidsangivelser.'),link('gn1','Forstå muntlige beskjeder og svare i enkel samtale.','teacher-led')],'Lærerledet og planlagt. Les uten synlig manus, gjenta ved behov. La eleven fortelle planen videre og stille ett spørsmål.','Jeg heter Mali. Jeg skal lese på skolen på tirsdag klokka tolv. Jeg har en bok og en penn. Hva skal jeg gjøre på tirsdag?',['Eleven får med hovedhandling og dag eller tid.','Eleven videreformidler noe av planen muntlig.','Observer behov for gjentakelse separat fra skriftlig arbeid.']);
  module('m04','Avtale, kjøpe og be om hjelp','a1',range(9,12),['Foreslå og bekrefte en avtale.','Lese pris og endring og skrive et enkelt behov.'],['Kjente dager, tider, ting og korte beskjeder.'],[link('gn1','Uttrykke behov og bruke hverdagsfraser.'),link('hk-norsk','Meldinger, invitasjoner og praktiske behov.'),link('gn1','Ta tur, avklare og svare muntlig.','teacher-led')],'Lærerledet og planlagt. Les invitasjonen uten synlig tekst. Bytt roller og la eleven be om oppklaring.','Kan vi møtes på mandag klokka åtte? Nei, det passer ikke. Kan vi møtes på tirsdag klokka tolv? Ja, det passer. Ta med en bok.',['Observer om den bekreftede avtalen oppfattes.','Eleven foreslår eller avslår med kjente fraser.','Øv på å be om gjentakelse eller forklaring.']);
  module('m05','Plan, rute og sammenligning','a1plus',range(13,16),['Bruke en enkel plan og forstå en kort rute.','Beskrive rekkefølge og sammenligne opplysninger.'],['Praktiske meldinger og kjent dag-/tids-/stedsinformasjon.'],[link('gn2','Tabeller, fagord, tekststruktur og grunnleggende språkregler.'),link('fov2','Videre språkstrategier og beskrivelser.'),link('gn2','Muntlig hovedinnhold og forståelig kommunikasjon.','teacher-led')],'Lærerledet og planlagt. Bruk et entydig kart med felles start og orientering. Les ruten uten synlig manus; eleven forklarer tilbake.','Norsk starter klokka ni. Start ved inngangen. Gå rett fram til krysset. Ta til venstre til rom 2.',['Eleven følger muntlige trinn fra riktig start.','Eleven gir en forståelig instruksjon.','Avklar språk og kartperspektiv separat.']);
  module('m06','Begrunnelse, problem og før/nå','a1plus',range(17,20),['Gi en enkel begrunnelse og problembeskjed.','Skille lærte fortidsformer fra nåtid og koble korte kilder.'],['Rekkefølge, V2 og sammenligning med støtte.'],[link('gn2','Meninger, struktur og språkstrategier.'),link('fov2','Språkutvikling og tilpasset tekst.'),link('hk-norsk','Kjente opplevelser, planer og meldinger.'),link('gn2','Muntlig forklaring og gjenfortelling.','teacher-led')],'Lærerledet og planlagt. Les en kort logg høyt. Eleven forteller hovedpunktet og gir en enkel grunn; bruk tidslinje ved behov.','I går leste Anna en bok. I dag skriver Anna en beskjed. Anna kommer klokka tolv fordi bussen er forsinket.',['Eleven skiller i går fra i dag.','Eleven gjenforteller et hovedpunkt.','Gi innholdsrespons og én relevant språkrespons.']);
  module('m07','Mat, fritid, reise og kontakt','a2',range(21,24),['Finne praktisk informasjon i meny, rutetabell og timekort.','Skrive ønsker, invitasjoner og enkel kontaktmelding.'],['Kort sammenhengende melding og praktiske kilder.'],[link('gn2','Hverdags-/fagtekster, tabeller og egne meninger.'),link('fov2','Praktisk kommunikasjon og språkferdigheter.'),link('hk-norsk','Enkle autentiske tekster og kjente situasjoner.'),link('hk-norsk','Lytting og muntlig samhandling i kjente situasjoner.','teacher-led')],'Lærerledet og planlagt. Velg rollesituasjon og les korte meldinger uten manus for eleven. La eleven velge relevant info og spørre.','Jeg vil gjerne ha brød. Bussen går klokka ni. Jeg vil bestille en time hos legen.',['Eleven oppfatter formål og relevant detalj.','Eleven stiller et relevant spørsmål.','Ingen må dele reell helse- eller personinformasjon.']);
  module('m08','Hendelser, ansvar og nærmiljø','a2',range(25,28),['Beskrive et kort hendelsesforløp med lærte former.','Forstå frist, oppslag og enkel fortelling.'],['Hverdagskilder og eksplisitte språkbroer.'],[link('gn2','Skjønnlitterære/faglige tekster og tekststruktur.'),link('fov2','Beskrivelser og språkferdigheter.'),link('hk-norsk','Opplevelser, planer og videreformidling.'),link('gn2','Samtale om innhold og kort gjenfortelling.','teacher-led')],'Lærerledet og planlagt. Les en fortelling uten synlig tekst. Eleven ordner stikkord, gjenforteller og svarer på et oppfølgingsspørsmål.','I går gikk Mali på skolen. Mali leste en bok og skrev en beskjed. I dag må Mali levere en oppgave.',['Eleven får fram hovedhendelser i rekkefølge.','Eleven ber om oppklaring ved behov.','Gi konkret respons på innhold og én språkform.']);
  module('m09','Vilkår, erfaring og samarbeid','a2plus',range(29,32),['Forstå vilkår og skrive en digital henvendelse.','Beskrive lærte erfaringer og knytte person til rolle.'],['Lærte fortidsformer, må/kan og funksjonell skriving.'],[link('gn2','Språklig sammenligning, tekststruktur og digitale ressurser.'),link('fov3','Språkstrategier og flerspråklighet.'),link('hk-norsk','Samhandling og videreformidling om opplæring og arbeid.'),link('gn2','Samtalebidrag og muntlig hovedinnhold.','teacher-led')],'Lærerledet og planlagt. Les en prosjektmelding; bruk ulike rollekort slik at elevene må avklare fordelingen muntlig.','Jeg tar med en jakke hvis det regner. Mali har lært å skrive en beskjed. Personen som leser, har boka.',['Eleven oppfatter et vilkår eller en rolle.','Elevene avklarer hvem som gjør hva.','Ikke krev ukjente former som ikke er undervist.']);
  module('m10','Synspunkt, nyhet og referanse','a2plus',range(33,36),['Uttrykke synspunkt og skille opplysning fra vurdering.','Følge referanser og forklare et handlingsforløp.'],['Enkle erfaringer og som-/hvis-mønstre med støtte.'],[link('gn2','Egne meninger, tekststruktur og språklig sammenligning.'),link('fov3','Språkstrategier og flerspråklige ressurser.'),link('gn3','Begrunne synspunkt og utforske tekster; delvis.'),link('gn3','Følge opp samtalebidrag og gjenfortelle muntlig.','teacher-led')],'Lærerledet og planlagt. Les to fiktive synspunkter uten synlig manus. Elevene gjengir dem og begrunner eget syn respektfullt.','Anna mener at gruppa trenger mer tid. Mali mener at gruppa kan levere i dag. Begge vil hjelpe en medelev.',['Eleven skiller hvem som mener hva.','Eleven spør om eller bygger videre på et bidrag.','Vurder begrunnelsen, ikke om læreren deler meningen.']);
  module('m11','Søknad, fagtekst og fortelling','b1',range(37,40),['Velge relevant informasjon til en henvendelse eller søknad.','Lese faglig/skjønnlitterær tekst og støtte tolkning med tekstbelegg.'],['Sammenhengende kort tekst, kildebevissthet og språkbroer.'],[link('gn3','Fagord, sjangre, begrunnelse og tekstforståelse.'),link('fov3','Fag-/språklæring og flerspråklige strategier.'),link('fov4','Arbeid mot bredere sluttmål; delvis.'),link('hk-norsk','Sammenheng om kjente opplærings- og arbeidsemner.'),link('gn3','Muntlig gjenfortelling og samtale.','teacher-led')],'Lærerledet og planlagt. Les et utdrag eller en arbeidshenvendelse høyt. Eleven gjenforteller, begrunner forståelsen og svarer på spørsmål.','Jeg har lært å samarbeide om en oppgave. Jeg ønsker å få praksis. Jeg kan fortelle hva jeg har gjort og spørre om det jeg trenger å vite.',['Eleven får fram hovedinnhold og relevant detalj.','Eleven forklarer uten å lese opp hele kilden.','Lærer vurderer muntlig/lytting separat fra nettarbeidet.']);
  module('m12','Kultur, kilder og eget prosjekt','b1',range(41,44),['Sammenligne synspunkt og språk-/kulturuttrykk med tekstbelegg.','Formidle flere kilder og bearbeide tekst for en mottaker.'],['Argumentasjonsstruktur, referanser, sjanger og kildeskille.'],[link('gn3','Argumentasjon, sjangre og språk-/kulturrefleksjon.'),link('fov4','Hensiktsmessige strategier og flerspråklig læring; delvis.'),link('hk-norsk','Sammenhengende tekster, samhandling og mediering.'),link('gn3','Muntlig presentasjon, respons og videre samtale.','teacher-led')],'Lærerledet og planlagt. Gi en kort muntlig prosjektbeskjed uten synlig manus. Eleven oppsummerer, gir forslag og svarer en medelev. Utforsk også lærerframført språkvariasjon med forklaring.','Gruppa skal planlegge en skoledag. Dere skal bruke to kilder og forklare hvorfor dere velger løsningen. En medelev trenger en kortere forklaring. Hvordan vil dere hjelpe?',['Eleven skiller kildeinnhold fra eget forslag.','Eleven tilpasser forklaring og følger opp respons.','Skriftlig sammenligning dekker ikke dialektlytting.']);
  return {title:'Språkverkstedet – fra første ord mot B1',scope:'52 temaer i et modulært forløp for ungdom og voksne. Egenøving i lesing og skriving kombineres med planlagte lærerledede muntlige og lytteaktiviteter. Skolen avklarer opplæringsgrunnlag; ingen nivåsertifisering.',checkedDate,modules,sources,limitations:[
    'Forløpet har egenøving og planlagte læreraktiviteter. Det er ikke et selvstendig fullstendig språkkurs eller en nivåprøve.',
    'A0–B1 er pedagogiske arbeidsnivåer/målretninger her. Oppgavegjennomføring dokumenterer ikke oppnådd CEFR-nivå.',
    'Læreplankoblinger er tematiske og pedagogiske, ikke juridisk læreplanoppfyllelse, rettighetsvurdering eller dokumentasjon på FOV-moduler/eksamenskompetanse.',
    'Egenøving forutsetter grunnleggende lese-/skriveferdigheter på et språk, eller særskilt tett lærerstøtte. A0 er ikke et komplett alfabetiseringskurs.',
    'Ingen lydopptak, automatisk lytting eller uttaleanalyse. Muntlig samhandling, lytting, uttale og språkvariasjon krever gjennomført lærerledet aktivitet og separat vurdering.',
    'Lærerskriptene er forslag. De kan leses høyt uten at eleven ser teksten. Å lese dem på skjermen er lesing, ikke lytting. Ingenting blir automatisk dokumentert som gjennomført.',
    'Frie tekster trenger egen-, medelev- eller lærerrespons. Lukkede fasiter er ikke generell grammatisk godkjenning.',
    'Ukrainsk/thai er kontekststøtte, ikke morsmålskontrollert oversettelse av et helt kurs. Andre språk og hjelpemidler kan brukes.',
    'Ord-/oppgaveantall og repetisjonsintervaller er praktiske valg, ikke læreplankrav eller forskningsbestemte garantier.'
  ]};
})();
